<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('agenda.view');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$t=(int)$user['tenant_id'];$sql="SELECT a.id,a.starts_at,a.ends_at,a.modality,a.meeting_url,p.name patient_name FROM appointments a JOIN patients p ON p.id=a.patient_id AND p.tenant_id=a.tenant_id WHERE a.tenant_id=:t AND a.starts_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) AND a.starts_at<DATE_ADD(NOW(),INTERVAL 365 DAY)";$p=['t'=>$t];if(in_array($user['role_slug'],['psychologist','supervised'],true)){$sql.=' AND a.professional_id=:u';$p['u']=$user['id'];}$st=db()->prepare($sql);$st->execute($p);$rows=$st->fetchAll();header('Content-Type: text/calendar; charset=utf-8');header('Content-Disposition: attachment; filename="psicomanager-agenda.ics"');echo "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//PsicoManager AI//Agenda//PT-BR\r\nCALSCALE:GREGORIAN\r\n";foreach($rows as $r){$uid='appointment-'.$r['id'].'@psicomanager';$s=(new DateTimeImmutable($r['starts_at'],new DateTimeZone((string)env('APP_TIMEZONE','America/Bahia'))))->setTimezone(new DateTimeZone('UTC'))->format('Ymd\THis\Z');$e=(new DateTimeImmutable($r['ends_at'],new DateTimeZone((string)env('APP_TIMEZONE','America/Bahia'))))->setTimezone(new DateTimeZone('UTC'))->format('Ymd\THis\Z');$summary='Atendimento - '.str_replace(["\r","\n",','],['','','\\,'],$r['patient_name']);$desc=$r['modality']==='online'?'Atendimento on-line '.($r['meeting_url']??''):'Atendimento presencial';echo "BEGIN:VEVENT\r\nUID:$uid\r\nDTSTART:$s\r\nDTEND:$e\r\nSUMMARY:$summary\r\nDESCRIPTION:".str_replace(',', '\\,',$desc)."\r\nEND:VEVENT\r\n";}echo "END:VCALENDAR\r\n";exit;
